import pty, os, subprocess, threading
def read_all(fd, buf):
    while True:
        try:
            d=os.read(fd,8192)
            if not d: break
            buf.append(d)
        except OSError: break

def test(cmd, stdout_tty, stderr_tty, env_extra=None, inp=b""):
    env=dict(os.environ)
    if env_extra: env.update(env_extra)
    if stdout_tty:
        m_out,s_out=pty.openpty(); out_t=s_out
    else:
        r,w=os.pipe(); m_out=r; out_t=w
    if stderr_tty:
        m_err,s_err=pty.openpty(); err_t=s_err
    else:
        r,w=os.pipe(); m_err=r; err_t=w
    p=subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=out_t, stderr=err_t, env=env)
    os.close(out_t); os.close(err_t)
    oc=[]; ec=[]
    t1=threading.Thread(target=read_all,args=(m_out,oc)); t2=threading.Thread(target=read_all,args=(m_err,ec))
    t1.start(); t2.start()
    if inp: p.stdin.write(inp)
    p.stdin.close(); p.wait(); t1.join(2); t2.join(2)
    print(cmd, stdout_tty, stderr_tty, "exit",p.returncode)
    print(" out",b''.join(oc))
    print(" err",b''.join(ec))

test(["sh","-c","echo OUT; echo ERR >&2; [ -t 1 ] && echo tty1_out; [ -t 2 ] && echo tty2_out; [ -t 1 ] && echo tty1_err >&2; [ -t 2 ] && echo tty2_err >&2"], True, False)
test(["sh","-c","echo OUT; echo ERR >&2; [ -t 1 ] && echo tty1_out; [ -t 2 ] && echo tty2_out; [ -t 1 ] && echo tty1_err >&2; [ -t 2 ] && echo tty2_err >&2"], False, True)
test(["sh","-c","echo OUT; echo ERR >&2; [ -t 1 ] && echo tty1_out; [ -t 2 ] && echo tty2_out"], False, False)
test(["./executable","testfilter"], False, True, inp=b"hello\n=== RUN TestX\n")
test(["./executable","testfilter"], True, False, inp=b"hello\n=== RUN TestX\n")
PY"}

