}

// Default returns the built-in configuration.
func Default() Config {
	return Config{
		LabelType:  LabelLong,
		BuildStyle: Style{Bold: true, Foreground: mustColor("yellow")},
		StartStyle: Style{Foreground: mustColor("lightBlack")},
		PassStyle:  Style{Foreground: mustColor("green")},
		FailStyle:  Style{Bold: true, Foreground: mustColor("red")},
		SkipStyle:  Style{Foreground: mustColor("lightBlack")},
		PassPackageStyle: Style{
			Foreground: mustColor("green"),
			Hide:       true,
		},
		FailPackageStyle: Style{
			Bold:       true,
			Foreground: mustColor("red"),
			Hide:       true,
		},
		CoverThreshold: 50,
		CoveredStyle:   Style{Foreground: mustColor("green")},
		UncoveredStyle: Style{Bold: true, Foreground: mustColor("yellow")},
		FileStyle:      Style{Foreground: mustColor("cyan")},
		LineStyle:      Style{Foreground: mustColor("magenta")},
	}
}

// LabelPrefix formats a label according to the configured label type.
func (c *Config) LabelPrefix(long, short string) string {
	switch c.LabelType {
	case LabelLong:
		return fmt.Sprintf("%-5s| ", long)
	case LabelShort:
		return fmt.Sprintf("%-2s ", short)
	default:
		return ""
	}
}

func candidateDirs() []string {
	cwd, _ := os.Getwd()
	dirs := []string{cwd}
	if os.Getenv("RICHGO_LOCAL") != "1" {
		dirs = append(dirs, build.Default.GOPATH, runtime.GOROOT(), os.Getenv("HOME"))
	}
	return dirs
}

// Load reads and merges every .richstyle file found in the candidate
// directories, in order.  Files that cannot be read or parsed are
// reported with the standard logger and otherwise ignored.
func Load() Config {
	cfg := Default()
	for _, dir := range candidateDirs() {
		for _, suffix := range []string{"", ".yaml", ".yml"} {
			path := filepath.Join(dir, ".richstyle"+suffix)
			data, err := os.ReadFile(path)
			if err != nil {
				if !os.IsNotExist(err) {
					log.Println("error reading from", path, ": ", err)
				}
				continue
			}
			next := cfg
			previousRemovals := cfg.Removals
			next.Removals = nil
			if err := yaml.Unmarshal(data, &next); err != nil {
				log.Println("error unmarshaling yaml from", path, ": ", err)
				continue
			}
			merged := make([]string, 0, len(previousRemovals)+len(next.Removals))
			merged = append(merged, previousRemovals...)
			merged = append(merged, next.Removals...)
			next.Removals = merged
			cfg = next
		}
	}
	return cfg
}
