type ColorKind int

const (
	ColorNone ColorKind = iota
	ColorStandard
	ColorPalette
	ColorRGB
)

// Color is a foreground/background color decoded from the YAML
// configuration.  The zero value renders no color at all.
type Color struct {
	Kind  ColorKind
	Index int // 0-15 for ColorStandard, 0-255 for ColorPalette
	R     int
	G     int
	B     int
}

var namedColors = map[string]int{
	"black":        0,
	"red":          1,
	"green":        2,
	"yellow":       3,
	"blue":         4,
	"magenta":      5,
	"cyan":         6,
	"white":        7,
	"lightBlack":   8,
	"lightRed":     9,
	"lightGreen":   10,
	"lightYellow":  11,
	"lightBlue":    12,
	"lightMagenta": 13,
	"lightCyan":    14,
	"lightWhite":   15,
}

var (
	hexColorPattern   = regexp.MustCompile(`^#([0-9a-fA-F]{2})([0-9a-fA-F]{2})([0-9a-fA-F]{2})$`)
	rgbPartPattern    = `(?:\d{1,3}|0[xX][0-9a-fA-F]{2})`
	rgbColorPattern   = regexp.MustCompile(`^(?i:rgb)\((` + rgbPartPattern + `), *(` + rgbPartPattern + `), *(` + rgbPartPattern + `)\)$`)
	indexColorPattern = regexp.MustCompile(`^(` + rgbPartPattern + `)$`)
)

func parseBytePart(s string) (int, error) {
	if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
		v, err := strconv.ParseUint(s[2:], 16, 8)
		if err != nil {
			return 0, err
		}
		return int(v), nil
	}
	v, err := strconv.ParseUint(s, 10, 8)
	if err != nil {
		return 0, err
	}
	return int(v), nil
}

// ParseColor parses a color as documented for .richstyle files.
func ParseColor(s string) (Color, error) {
	if s == "" || s == "default" {
		return Color{Kind: ColorNone}, nil
	}
	if idx, ok := namedColors[s]; ok {
		return Color{Kind: ColorStandard, Index: idx}, nil
	}
	if m := hexColorPattern.FindStringSubmatch(s); m != nil {
		r, _ := strconv.ParseUint(m[1], 16, 8)
		g, _ := strconv.ParseUint(m[2], 16, 8)
		b, _ := strconv.ParseUint(m[3], 16, 8)
		return Color{Kind: ColorRGB, R: int(r), G: int(g), B: int(b)}, nil
	}
	if m := rgbColorPattern.FindStringSubmatch(s); m != nil {
		r, err1 := parseBytePart(m[1])
		g, err2 := parseBytePart(m[2])
		b, err3 := parseBytePart(m[3])
		if err1 != nil || err2 != nil || err3 != nil {
			return Color{}, errors.New("invalid format")
		}
		return Color{Kind: ColorRGB, R: r, G: g, B: b}, nil
	}
	if m := indexColorPattern.FindStringSubmatch(s); m != nil {
		v, err := parseBytePart(m[1])
		if err != nil {
			return Color{}, errors.New("invalid format")
		}
		return Color{Kind: ColorPalette, Index: v}, nil
	}
	return Color{}, errors.New("invalid format")
}

