		if c.Index < 8 {
			return strconv.Itoa(30 + c.Index)
		}
		return strconv.Itoa(90 + c.Index - 8)
	case ColorPalette:
		return fmt.Sprintf("38;5;%d", c.Index)
	case ColorRGB:
		return fmt.Sprintf("38;2;%d;%d;%d", c.R, c.G, c.B)
	default:
		return ""
	}
