	default:
		return ""
	}
}

// Style is a text decoration that can be configured per kind of line.
type Style struct {
	Hide       bool  `yaml:"hide"`
	Bold       bool  `yaml:"bold"`
	Faint      bool  `yaml:"faint"`
	Italic     bool  `yaml:"italic"`
	Underline  bool  `yaml:"underline"`
	BlinkSlow  bool  `yaml:"blinkSlow"`
	BlinkRapid bool  `yaml:"blinkRapid"`
	Inverse    bool  `yaml:"inverse"`
	Conceal    bool  `yaml:"conceal"`
	CrossOut   bool  `yaml:"crossOut"`
	Frame      bool  `yaml:"frame"`
	Encircle   bool  `yaml:"encircle"`
	Overline   bool  `yaml:"overline"`
	Foreground Color `yaml:"foreground"`
	Background Color `yaml:"background"`
}

// Prefix returns the escape sequences that switch this style on.
func (s *Style) Prefix() string {
	if s == nil {
		return ""
	}
	var b strings.Builder
	if code := s.Background.BackgroundCode(); code != "" {
		b.WriteString("\x1b[")
		b.WriteString(code)
		b.WriteString("m")
	}
	if code := s.Foreground.ForegroundCode(); code != "" {
		b.WriteString("\x1b[")
		b.WriteString(code)
		b.WriteString("m")
	}
	attrs := []struct {
		on   bool
		code string
	}{
		{s.Bold, "1"},
		{s.Faint, "2"},
		{s.Italic, "3"},
		{s.Underline, "4"},
		{s.BlinkSlow, "5"},
		{s.BlinkRapid, "6"},
		{s.Inverse, "7"},
		{s.Conceal, "8"},
		{s.CrossOut, "9"},
		{s.Frame, "51"},
		{s.Encircle, "52"},
		{s.Overline, "53"},
	}
	for _, a := range attrs {
