package editor

import (
	"regexp"
	"strconv"
	"strings"

	"richgo/config"
)

const (
	specialNone = iota
	specialBuildWithoutBracket
	specialOKWithoutSuffix
)

var (
	filePattern = regexp.MustCompile(`([^\s:]+\.go)(:\d+(?::\d+)?)`)

	buildWithBracketPattern = regexp.MustCompile(`^# ([^ ]+) \[([^\[\] ]+)\]$`)
	buildBarePattern        = regexp.MustCompile(`^# ([^ ]*)$`)
	startPattern            = regexp.MustCompile(`^=== RUN   Test(.*)$`)
	passTestPattern         = regexp.MustCompile(`^[ \t]*--- PASS: Test(.*)$`)
	failTestPattern         = regexp.MustCompile(`^[ \t]*--- FAIL: Test(.*)$`)
	skipTestPattern         = regexp.MustCompile(`^[ \t]*--- SKIP: Test(.*)$`)

	okBarePattern     = regexp.MustCompile(`^ok[ \t]+([^ \t]*)$`)
	okTrailingPattern = regexp.MustCompile(`^ok[ \t]+([^ \t]+)[ \t]+$`)
	okCoverPattern    = regexp.MustCompile(`^ok[ \t]+([^ \t]+)(?:[ \t]+(?:[\d.]+\w+|\(cached\)))?[ \t]+(coverage: \d+\.\d+% of statements)[ \t]*$`)
	okSuffixPattern   = regexp.MustCompile(`^ok[ \t]+([^ \t]+)[ \t]+(?:(?:[\d.]+\w+|\(cached\))(?:[ \t]+\[(?:no tests to run|no test files)\])?|\[(?:no tests to run|no test files)\])[ \t]*$`)

	failPackagePattern = regexp.MustCompile(`^FAIL[ \t]+[^ \t]+[ \t]+(?:[\d.]+\w+|\[build failed\])$`)
	questionPattern    = regexp.MustCompile(`^\?[ \t]+([^ \t]+[ \t]+\[no test files\])$`)
	alonePattern       = regexp.MustCompile(`^(PASS|FAIL)[ \t]*$`)
	coverPattern       = regexp.MustCompile(`^coverage: (\d+\.\d)% of statements$`)
)

type testEditor struct {
	cfg      config.Config
	removals []*regexp.Regexp
	current  *config.Style
	hidden   bool
}

// NewTest creates the editor that enriches `go test` output.  Invalid
// removal patterns panic here, exactly as a MustCompile would suggest.
func NewTest(cfg config.Config) Editor {
	editor := &testEditor{cfg: cfg}
	for _, removal := range cfg.Removals {
		editor.removals = append(editor.removals, regexp.MustCompile(removal))
	}
	return editor
}

type decoded struct {
	category   bool
	plain      string
	style      *config.Style
	special    int
	update     bool
	nextHidden bool
}

func (t *testEditor) classify(body string) decoded {
	cfg := &t.cfg

	if buildWithBracketPattern.MatchString(body) {
		style := cfg.BuildStyle
		return decoded{
			category: true,
			plain:    cfg.LabelPrefix("BUILD", "!!") + body[2:],
			style:    &style,
			update:   true, nextHidden: style.Hide,
		}
	}
	if buildBarePattern.MatchString(body) {
		style := cfg.BuildStyle
		return decoded{
			category: true,
			plain:    cfg.LabelPrefix("BUILD", "!!") + body[2:],
			style:    &style,
			special:  specialBuildWithoutBracket,
			update:   true, nextHidden: style.Hide,
		}
	}

	if m := startPattern.FindStringSubmatch(body); m != nil {
		style := cfg.StartStyle
		content := m[1]
		if cfg.LeaveTestPrefix {
			content = "Test" + content
		}
		indent := strings.Repeat(" ", strings.Count(content, "/")*2)
		return decoded{
			category: true,
			plain:    cfg.LabelPrefix("START", ">") + indent + content,
			style:    &style,
			update:   true, nextHidden: false,
		}
	}

	for _, spec := range []struct {
		pattern     *regexp.Regexp
		word        string
		long, short string
		style       config.Style
	}{
		{passTestPattern, "PASS", "PASS", "o", cfg.PassStyle},
		{failTestPattern, "FAIL", "FAIL", "x", cfg.FailStyle},
		{skipTestPattern, "SKIP", "SKIP", "-", cfg.SkipStyle},
	} {
		if !spec.pattern.MatchString(body) {
			continue
		}
		style := spec.style
		trimmed := strings.TrimLeft(body, " ")
		prefix := "--- " + spec.word + ": "
		var content string
		if strings.HasPrefix(trimmed, prefix) {
			after := trimmed[len(prefix):]
			if cfg.LeaveTestPrefix {
				content = after
			} else {
				content = strings.TrimPrefix(after, "Test")
			}
		} else {
			content = trimmed
		}
		indent := strings.Repeat(" ", strings.Count(content, "/")*2)
		return decoded{
			category: true,
			plain:    cfg.LabelPrefix(spec.long, spec.short) + indent + content,
			style:    &style,
			update:   true, nextHidden: style.Hide,
		}
	}

	if m := okCoverPattern.FindStringSubmatch(body); m != nil {
		style := cfg.PassStyle
		return decoded{
			category: true,
			plain:    cfg.LabelPrefix("PASS", "o") + m[1] + " " + m[2],
			style:    &style,
			update:   true, nextHidden: style.Hide,
		}
	}
	if m := okSuffixPattern.FindStringSubmatch(body); m != nil {
		style := cfg.PassStyle
