// mergeDuplicateKeys rewrites a parsed YAML tree so that repeated
// mapping keys are resolved the way the reference configuration
// loader resolves them: the last scalar/sequence value wins, while
// repeated mappings are merged key by key.
func mergeDuplicateKeys(node *yaml.Node) {
	if node == nil {
		return
	}
	switch node.Kind {
	case yaml.DocumentNode, yaml.SequenceNode:
		for _, child := range node.Content {
			mergeDuplicateKeys(child)
		}
	case yaml.MappingNode:
		for i := 0; i+1 < len(node.Content); i += 2 {
			mergeDuplicateKeys(node.Content[i])
			mergeDuplicateKeys(node.Content[i+1])
		}
		var merged []*yaml.Node
		for i := 0; i+1 < len(node.Content); i += 2 {
			key := node.Content[i]
			value := node.Content[i+1]
			if key.Kind != yaml.ScalarNode {
				merged = append(merged, key, value)
				continue
			}
			found := -1
			for j := 0; j+1 < len(merged); j += 2 {
				if merged[j].Kind == yaml.ScalarNode && merged[j].Value == key.Value {
					found = j
					break
				}
			}
			if found < 0 {
				merged = append(merged, key, value)
				continue
			}
			existing := merged[found+1]
			if existing.Kind == yaml.MappingNode && value.Kind == yaml.MappingNode {
				existing.Content = append(existing.Content, value.Content...)
				mergeDuplicateKeys(existing)
				continue
			}
			merged = append(merged[:found], merged[found+2:]...)
			merged = append(merged, key, value)
		}
		node.Content = merged
	}
}

'''
