{"command":"cat > config/config_test.go <<'EOF'
package config

import "testing"

func TestParseColor(t *testing.T) {
	tests := []struct {
		in   string
		fore string
		back string
	}{
		{"", "", ""},
		{"default", "", ""},
		{"red", "31", "41"},
		{"lightBlue", "94", "104"},
		{"123", "38;5;123", "48;5;123"},
		{"0xF", "38;5;15", "48;5;15"},
		{"#010203", "38;2;1;2;3", "48;2;1;2;3"},
		{"rgb(4, 5, 6)", "38;2;4;5;6", "48;2;4;5;6"},
	}
	for _, tt := range tests {
		c, err := ParseColor(tt.in)
		if err != nil {
			t.Fatalf("ParseColor(%q): %v", tt.in, err)
		}
		if got := c.ForegroundCode(); got != tt.fore {
			t.Errorf("ParseColor(%q) foreground = %q, want %q", tt.in, got, tt.fore)
		}
		if got := c.BackgroundCode(); got != tt.back {
			t.Errorf("ParseColor(%q) background = %q, want %q", tt.in, got, tt.back)
		}
	}
	if _, err := ParseColor("not-a-color"); err == nil {
		t.Fatal("ParseColor(not-a-color) unexpectedly succeeded")
	}
}

func TestLabelPrefixAndDefaults(t *testing.T) {
	cfg := Default()
	if cfg.CoverThreshold != 50 || cfg.LabelType != LabelLong {
		t.Fatalf("unexpected defaults: %+v", cfg)
	}
	if got := cfg.LabelPrefix("PASS", "o"); got != "PASS | " {
		t.Fatalf("long label = %q", got)
	}
	cfg.LabelType = LabelShort
	if got := cfg.LabelPrefix("PASS", "o"); got != "o  " {
		t.Fatalf("short label = %q", got)
	}
	cfg.LabelType = LabelNone
	if got := cfg.LabelPrefix("PASS", "o"); got != "" {
		t.Fatalf("none label = %q", got)
	}
}
EOF
