def run(exe,pct):
 e=dict(os.environ);e["RICHGO_FORCE_COLOR"]="1";p=subprocess.run([exe,"testfilter"],input=f"coverage: {pct}% of statements\n".encode(),capture_output=True,env=e,cwd="/tmp");return p.returncode,p.stdout,(p.stderr.splitlines() or [b''])[0]
for pct in ["0.0","109.9","110.0","999.9","000110.0","9223372036854775807.0","9223372036854775808.0","18446744073709551615.0"]:
 a=run("/workspace/executable",pct);b=run("/tmp/myrichgo",pct);print(pct,a==b,a,b)
PY"}

