{"command":"python3 - << 'PY'
import subprocess,os,signal
for exe in ["/workspace/executable","/tmp/myrichgo"]:
 for mode in [["testfilter"],["version"]]:
  p=subprocess.Popen([exe]+mode,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,env={**os.environ,"RICHGO_FORCE_COLOR":"1"},cwd="/tmp")
  try:
   out,err=p.communicate(b"hello\n"*10000, timeout=2) if mode==["testfilter"] else p.communicate(b"",timeout=2)
   print(exe,mode,p.returncode,len(out),len(err))
  except Exception as e: print(exe,mode,e)
 # broken pipe: close read end after start using shell pipeline head
 cmd=f"printf '%s\\n' '--- PASS: TestA (0s)' | {exe} testfilter | head -c 0; echo pipeline:${{PIPESTATUS[*]}}"
 p=subprocess.run(["bash","-c",cmd],capture_output=True,env={**os.environ,"RICHGO_FORCE_COLOR":"1"},cwd="/tmp")
 print(exe,"head0",p.returncode,p.stdout,p.stderr)
PY"}

